import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    W = int(next(it))
    H = int(next(it))
    N = int(next(it))
    devices = []
    for _ in range(N):
        x = int(next(it))
        y = int(next(it))
        devices.append((x, y))

    # Precompute prefix sums for rows and columns
    row_prefix = [0] * (H + 1)
    for i in range(1, H + 1):
        row_prefix[i] = row_prefix[i - 1] + (1 if i <= W else 0)

    col_prefix = [0] * (W + 1)
    for j in range(1, W + 1):
        col_prefix[j] = col_prefix[j - 1] + (1 if j <= H else 0)

    # Sort devices by x ascending, then y ascending
    devices.sort(key=lambda p: (p[0], p[1]))

    # dp[i] = max nuggets collected when activating device i as the last device
    dp = [0] * N

    for i in range(N):
        x, y = devices[i]
        # Base nuggets on the device square
        base = 1
        # East direction
        if x + 1 <= W:
            # Find the first device to the east with y-coordinate > y
            j = i + 1
            while j < N and devices[j][1] <= y:
                j += 1
            if j < N:
                next_x = devices[j][0]
                east = next_x - x - 1
            else:
                east = W - x
            base += east
        # West direction
        if x - 1 >= 1:
            # Find the first device to the west with y-coordinate > y
            j = i - 1
            while j >= 0 and devices[j][1] <= y:
                j -= 1
            if j >= 0:
                next_x = devices[j][0]
                west = x - next_x - 1
            else:
                west = x - 1
            base += west
        # South direction
        if y - 1 >= 1:
            # Find the first device below with x-coordinate > x
            j = i + 1
            while j < N and devices[j][0] <= x:
                j += 1
            if j < N:
                next_y = devices[j][1]
                south = next_y - y - 1
            else:
                south = H - y
            base += south
        # North direction
        if y + 1 <= H:
            # Find the first device above with x-coordinate > x
            j = i + 1
            while j < N and devices[j][0] <= x:
                j += 1
            if j < N:
                next_y = devices[j][1]
                north = next_y - y - 1
            else:
                north = H - y
            base += north

        # Add nuggets from rows and columns that are fully collected
        # Rows above y that are fully collected
        for r in range(y + 1, H + 1):
            if row_prefix[r] == W:
                base += W
        # Rows below y that are fully collected
        for r in range(1, y):
            if row_prefix[r] == W:
                base += W
        # Columns left of x that are fully collected
        for c in range(1, x):
            if col_prefix[c] == H:
                base += H
        # Columns right of x that are fully collected
        for c in range(x + 1, W + 1):
            if col_prefix[c] == H:
                base += H

        dp[i] = base

    print(max(dp) if dp else 0)

if __name__ == "__main__":
    solve()
